contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint depositAmount, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount, "test contract has enough Ether");

        c.sendMoney(address(this), depositAmount); if (__ESBMC_reverted()) return;

        uint balanceBefore = address(c).balance;
        require(balanceBefore >= withdrawAmount, "C has enough balance for withdrawal");

        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = address(c).balance;

        assert(!reverted && balanceBefore - balanceAfter == withdrawAmount);
    }
}

