// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 depositAmount, uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.sendMoney(address(this), depositAmount) {} catch { return; }
        uint balanceBefore = address(c).balance;
        vm.assume(balanceBefore >= withdrawAmount);
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;
        assertTrue(!reverted && balanceBefore - balanceAfter == withdrawAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 withdrawAmount) public {
        _run(depositAmount, withdrawAmount);
    }

    receive() external payable {}
}
